from itertools import permutations

def is_costas(p):
    n = len(p)
    for dc in range(1, n):
        seen = set()
        for c in range(n - dc):
            dr = p[c+dc] - p[c]
            if dr in seen:
                return False
            seen.add(dr)
    return True

n = 12
fixed = {3: 8, 8: 2}
used = set(fixed.values())
cols = [c for c in range(n) if c not in fixed]
rows_avail = [r for r in range(n) if r not in used]

x = [0]*n
for c,r in fixed.items():
    x[c] = r

# backtrack
def backtrack(idx, avail):
    if idx == len(cols):
        # check full
        if is_costas(x):
            return True
        return False
    c = cols[idx]
    for r in list(avail):
        x[c] = r
        # partial check: check displacement vectors so far are distinct
        # full check at end is fine but slow; do incremental
        avail.remove(r)
        if backtrack(idx+1, avail):
            return True
        avail.add(r)
    return False

# Better: incremental check
def check_partial(assigned_cols):
    # assigned_cols is list of columns currently assigned
    # compute all displacement vectors among assigned columns, check distinct
    pairs = {}
    cs = sorted(assigned_cols)
    for i in range(len(cs)):
        for j in range(i+1, len(cs)):
            dc = cs[j]-cs[i]
            dr = x[cs[j]]-x[cs[i]]
            key = (dc, dr)
            if key in pairs:
                return False
            pairs[key] = True
    return True

assigned = set(fixed.keys())

def bt(idx, avail):
    if idx == len(cols):
        return True
    c = cols[idx]
    for r in list(avail):
        x[c] = r
        assigned.add(c)
        if check_partial(assigned):
            avail.remove(r)
            if bt(idx+1, avail):
                return True
            avail.add(r)
        assigned.remove(c)
    return False

avail = set(rows_avail)
